TLM.f("Sancti/01-27",{"officium":"S. Joannis Chrysostomi Episcopi Confessoris Ecclesiæ Doctoris","rule":["vide C4a","Gloria","CredoDA"],"ruleInherited":["Gloria"],"fallback":"Commune/C4a","from":{"GradualeP":"Commune/C4a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Ecclésiam tuam, quǽsumus, Dómine, grátia cœléstis amplíficet: quam beáti Joánnis Chrysóstomi Confessóris tui atque Pontíficis illustráre voluísti gloriósis méritis et doctrínis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 4:1-8"},{"k":"text","la":"Caríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importune: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magistros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum ímple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus."}],"Graduale":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est inventus símilis illi, qui conserváret legem Excélsi."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jac 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis,"},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum."}],"Offertorium":[{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sancti Joánnis Chrysóstomi Pontíficis tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Ut nobis, Dómine, tua sacrifícia dent salútem: beátus Joánnes Chrysóstomus Póntifex tuus et Doctor egrégius, quǽsumus, precátor accédat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"f17bbac22be741ea":{"t":"Sir 15, 5, Ps 91, 2\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. (Ps. 91, 2) Dobro je slaviti Gospodina i pjevati imenu tvojem, Višnji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave.","kn":"(Crkv. 15, 5). Usred Crkve otvorio je Gospodin njegova usta i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave (Aleluja, aleluja). (Ps. 91, 2.) Dobro je slaviti Gospodina i pjevati Imenu Tvomu,^ Višnji! Slava Ocu... Usred Crkve...","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"},"e13ac1f8dcd70c46":{"t":"<i>Pomolimo se</i>.\nNebeska milost obogatila. Gospodine, tvoju Crkvu koju si htio prosvijetliti slavnim zaslugama i naukom blaženog Ivana Zlatoustoga tvoga priznavaoca i biskupa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da Tvoja utvrđuje Crkvu Tvoju, koju si htio da prosvijetliš slavnim zaslugama i naukama blaženog Ivana Zlatoustog, priznavaoca i biskupa svoga, po G. n.","knRef":"Kniewald 1942, str. 492–493 (snimka 247) (OCR)"},"c97d830457c280ab":{"t":"2 Tim 4, 1-8\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi, zaklinjem te pred Bogom i Isusom Kristom koji će suditi žive i mrtve njegovim dolaskom i njegovim kraljevstvom, propovijedaj riječ, revnuj u zgodno i nezgodno vrijeme, karaj, moli, opominji sa svom strpljivošću i naukom. Jer će doći vrijeme kad neće primati zdrave nauke, nego će oko sebe skupiti naučitelje po svojim požudama koji će im ugađati ušima. Odvraćat će uši od istine, a obraćat će ih k bajkama. Ali ti bdij, budi u svemu strpljiv, izvršuj djelo evanđeliste, ispunjavaj svoju službu. Budi trijezan! Ja sam već žrtvovan i vrlo je blizu vrijeme moje smrti. Dobar sam boj bio, tijek svršio, vjeru održao. Na kraju mi je pripravljen vijenac pravde koji će mi u onaj dan dati Gospodin, pravedni sudac, ali ne samo meni, nego i onima koji ljube njegov dolazak.","kn":"Čitanje poslanice bi. Pavla apostola Timoteju (II, 4, 1-8). Predragi! Zaklinjem te pred Bogom i Isusom Kristom, koji će suditi žive i mrtve, njegovim dolaskom 1 njegovim kraljevstvom: Propovijedaj riječ, revnuj u zgodno i nezgodno vrijeme, karaj, moli, opominji sa svom strpljivošću i naukom. Jer će doći vrijeme, kad ne će primati zdrave nauke, nego će oko sebe skupiti učitelje po svojim požudama, kakio ugađa ušima. Odvraćat će uši od istine, a obraćat će se k bajkama. Ali ti bdij, budi u svemu strpljiv, izvršuj djelo kao evanđelist, ispunjavaj svoju službu. Budi trijezan! Jer ja se već žrtvujem i vrlo je blizu vrijeme moje smrti. Vojevao sam dobar boj, dovršio trku, sačuvao vjeru. Na kraju pripravljen mi je vijenac pravde, koji će mi u onaj dan dati Gospodin, pravedan sudac; ali ne samo meni, nego i onima, koji ljube njegov dolazak.","knRef":"Kniewald 1942, str. 470–471 (snimka 236) (OCR)"},"cb560eea85401d93":{"t":"Sir 44, 16, Sir 44, 20\n(Sir 44, 16) Evo velikog svećenika koje se za svoga života svidio Bogu. (Sir 44, 20) Nitko mu nije bio ravan u izvršavanju zakona Svevišnjega.\n\nJak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>.","kn":"(Psi 44, 16). Evo velikog svećenika, koji je za svoga života bio Bogu mio. (Crkv. 44, 20). I nitko mu nije bio ravan u držanju zakona Višnjega.\n\nAleluja, aleiuja. (Jak. 1, 12) Blago čovjeku, koji pretrpi napast, jer će primiti vijenac slave, kad bude prokušan, aleluja.","knRef":"Kniewald 1942, str. 450–451 (snimka 226) (OCR)"},"a220bcd1476c8c48":{"t":"Mt 5, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Vi ste sol zemlje. Ako sol izvjetri, čim će se soliti? Za ništa više ne vrijedi, nego da se izbaci i da je ljudi pogaze. Vi ste svjetlo svijeta. Ne može se sakriti grad sazidan na gori. Niti se upaljuje svijeća i postavlja pod varićak, nego na svijećnjak da svijetli svima koji su u kući. Tako neka svijetli vaše svjetlo pred ljudima da vide vaša dobra djela i slave vašega nebeskog Oca. Nemojte misliti da sam došao ukinuti zakon ili proroke! Nisam došao ukinuti nego dopuniti. Zaista vam kažem, dok stoji nebo i zemlja, neće od zakona nestati ni jednog slova, niti jednog znaka, dok se sve ne ispuni. Tko, dakle, dokine jednu od ovih najmanjih zapovijedi i tako nauči ljude, bit će najmanji u kraljevstvu nebeskom. A tko bude vršio i naučavao, taj će biti velik u kraljevstvu nebeskom.","kn":"t Slijedi sveto evanđelje po Mateju (5, 13-19). U ono vrijeme reče Isus svojim učenicima: Vi ste sol ze^ji. Ako se sol pokvari, čim će se soliti? Nije više ni zašto, nego da se baci van, da je pogaze ljudi. Vi ste svijetlo svijetu. Ne može se sakriti na gori sazidan grad. Niti se upaljuje svijetlo i po- stavlja pod posudu, nego na svijećnjak, da svijetli svima u kući. Tako neka svijetli vaše svijetlo pred ljudima, da vide vaša dobra djela i slave vašega nebeskog Oca. Nemojte misliti, da sam došao ukinuti zakon ili proroke! Nijesam došao ukinuti, nego dopuniti. Zaista vam kažem, dok ne prođe nebo i zemlja, ne će od zakona nestati ni jednoga slova ni jednoga znaka, dok se ne ispuni sve. Tko, 'dakle, dokine jednu od ovUi najmanjih zapovijedi i tako nauči ljude, bit će najmanji u kraljevstvu nebeskom, a tko bude vršio i naučavao, taj će biti velik u kraljevstvu nebeskom.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"26bc9b7e0a4c66c8":{"t":"Ps 91, 13\nPravednik cvate kao palma i raste kao libanski cedar.","kn":"(Ps. 91, 13). Pravednik cvate poput paome i raste poput libanskog cedra.","knRef":"Kniewald 1942, str. 608–609 (snimka 305) (OCR)"},"c4970c1fc499e285":{"t":"Neka nam, Gospodine, pomogne pobožna molitva svetoga Ivana Zlatoustoga tvoga biskupa i naučitelja, i neka njegova molitva učini da ti naši darovi budu prijatni i isprosi nam oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nam. Gospodine, sveti Petar, biskup Tvoj i naučitelj, ne uskrati svoje pobožne molitve, nego neka svojom molitvom naše darove učini Tebi prijatnima,, a nama neka uvijek pribavlja Tvoje oprošten je. Po G. n. ,","knRef":"Kniewald 1942, str. 512–513 (snimka 257) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada.","kn":"(Lk. 12, 42). Evo razboritog i vjernog upravitelja, koga postavi Gospodin nad družinom svojom, da im na vrijeme daje hranu, koja im pripada.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"ef2399ea62cf1dfd":{"t":"<i>Pomolimo se</i>.\nNeka se zauzme za nas, molimo, Gospodine, blaženi Ivan Zlatousti tvoj biskup i naučitelj, da nam tvoje žrtve donesu spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da Tvoja utvrđuje Crkvu Tvoju, koju si htio da prosvijetliš slavnim zaslugama i naukama blaženog Ivana Zlatoustog, priznavaoca i biskupa svoga, po G. n.","knRef":"Kniewald 1942, str. 492–493 (snimka 247) (OCR)"},"01468bf369412f44":{"t":"Sir 44, 16, Sir 44, 20\n(Sir 44, 16) Evo velikog svećenika koje se za svoga života svidio Bogu. (Sir 44, 20) Nitko mu nije bio ravan u izvršavanju zakona Svevišnjega.\n\nPs 111, 1-3\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. Silno će biti na zemlji njegovo potomstvo, rod će pravednika biti blagoslovljen. U njegovu je domu slava i bogatstvo, i njegova pravednost ostaje u vijeke vjekova.","kn":"(Psi 44, 16). Evo velikog svećenika, koji je za svoga života bio Bogu mio. (Crkv. 44, 20). I nitko mu nije bio ravan u držanju zakona Višnjega.\n\n(Ps. 111, 1-3). Blago čovjeku, koji poštuje Boga, zapovijedi njegove žudi veoma. Silno na zemlji bit će potomstvo njegovo, blagoslovit će še rod pravednih. Slava i bogatstvo u domu njegovu, i pravda njegova ostaje u vijeke vijeka.","knRef":"Kniewald 1942, str. 450–451 (snimka 226) (OCR)"}}});
